        ///<summary>
        ///Give an escrow's frozen holdings back to the creator of each asset, and opt the escrow out.
        ///
        ///WAL-05: the ledger closes a frozen holding only to the asset's creator, and an escrow that
        ///still holds an asset cannot be deleted. Anyone who can make an escrow opt in can leave it
        ///a frozen unit of an asset of their own. arc58_reclaim never redirects a close-out by itself:
        ///the admin names the assets to give up here. A holding that is not frozen is refused, because
        ///arc58_reclaim returns it to the controlled address.
        ///</summary>
        /// <param name="escrow">The escrow that holds the frozen assets </param>
        /// <param name="assets">The frozen assets to close out to their creators </param>
        public async Task Arc58CloseFrozenToCreator(string escrow, ulong[] assets, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
        {
            _tx_boxes ??= new List<BoxRef>();
            _tx_transactions ??= new List<Transaction>();
            _tx_assets ??= new List<ulong>();
            _tx_apps ??= new List<ulong>();
            _tx_accounts ??= new List<Address>();
            byte[] abiHandle = { 35, 187, 72, 102 };
